757	/**
758	 * Resolve the auto memory directory for a given working directory.
759	 * Mirrors Claude Code's path derivation from git root.
760	 */
761	export function resolveAutoMemoryDir(workingDir: string): string {
762	  const gitRoot = findGitRoot(workingDir);
763	  const basePath = gitRoot || workingDir;
764	
765	  // Claude Code normalizes to forward slashes then replaces both `/` and `_`
766	  // with dashes (e.g. /workspaces/RX_ERP -> -workspaces-RX-ERP). The leading
767	  // dash IS preserved.
768	  const normalized = basePath.split(path.sep).join('/');
769	  const projectKey = normalized.replace(/[\/_]/g, '-');
770	
771	  return path.join(
772	    process.env.HOME || process.env.USERPROFILE || '~',
773	    '.claude',
774	    'projects',
775	    projectKey,
776	    'memory',
777	  );
778	}
