771	   * Acquire a resource from the pool
772	   */
773	  async acquire(): Promise<T> {
774	    // Try to find an available resource
775	    for (const pooled of this.pool) {
776	      if (!pooled.inUse && this.validate(pooled.resource)) {
777	        pooled.inUse = true;
778	        pooled.lastUsedAt = Date.now();
779	        pooled.useCount++;
780	        return pooled.resource;
781	      }
782	    }
783	
784	    // Create new resource if under max
785	    if (this.pool.length < this.maxSize) {
786	      const resource = await this.create();
787	      const pooled: PooledResource<T> = {
788	        resource,
789	        inUse: true,
790	        createdAt: Date.now(),
791	        lastUsedAt: Date.now(),
792	        useCount: 1,
793	      };
794	      this.pool.push(pooled);
795	      return resource;
796	    }
797	
798	    // Wait for available resource
799	    return new Promise((resolve, reject) => {
800	      const timeoutId = setTimeout(() => {
801	        const index = this.waitQueue.findIndex((w) => w.resolve === resolve);
802	        if (index !== -1) {
803	          this.waitQueue.splice(index, 1);
804	        }
805	        reject(new Error('Acquire timeout'));
806	      }, this.acquireTimeoutMs);
807	
808	      this.waitQueue.push({ resolve, reject, timeoutId });
809	    });
810	  }
