43	export async function fetchAgentCard(
44	  baseOrCardUrl: string,
45	  options: FetchAgentCardOptions = {},
46	): Promise<FetchAgentCardResult> {
47	  const fetchImpl = options.fetchImpl ?? globalThis.fetch;
48	  if (typeof fetchImpl !== 'function') {
49	    throw new Error('fetchAgentCard: no fetch implementation available');
50	  }
51	  const sourceUrl = resolveAgentCardUrl(baseOrCardUrl);
52	  const maxBytes = options.maxBytes ?? 256 * 1024;
53	
54	  const controller = new AbortController();
55	  const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? 10_000);
56	  let text: string;
57	  try {
58	    const res = await fetchImpl(sourceUrl, {
59	      signal: controller.signal,
60	      headers: { accept: 'application/json' },
61	    });
62	    if (!res.ok) {
63	      throw new Error(`fetchAgentCard: ${sourceUrl} returned HTTP ${res.status}`);
64	    }
65	    text = await res.text();
66	  } finally {
67	    clearTimeout(timer);
68	  }
69	  if (text.length > maxBytes) {
70	    throw new Error(`fetchAgentCard: card exceeds ${maxBytes} bytes`);
71	  }
72	
73	  let parsed: unknown;
74	  try {
75	    parsed = JSON.parse(text);
76	  } catch {
77	    throw new Error(`fetchAgentCard: ${sourceUrl} did not return valid JSON`);
78	  }
